//! Replays the Node oracle sets in `tests/fixtures/rust-core/ir` (generated by
//! `benchmarks/rust-core-oracles/ir.oracle.test.ts`).

use risunest_ir::chat::{Multimodal, PromptMessage};
use risunest_ir::{json, num, Budget, Error, Limits, OwnedVec, Text, Value};
use serde_json::Value as Json;
use sha2::{Digest, Sha256};
use std::sync::{atomic::AtomicBool, Arc};

macro_rules! oracle_set {
    ($set:literal) => {
        load($set,
            include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"), "/../../../tests/fixtures/rust-core/ir/", $set, ".cases.json")),
            include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"), "/../../../tests/fixtures/rust-core/ir/", $set, ".expected.json")))
    };
}

fn budget() -> Budget {
    let limits = Limits { max_owned_bytes: 256 << 20, max_json_bytes: 16 << 20, max_text_units: 16 << 20, max_values: 1 << 20,
        max_depth: 128, max_work: 1 << 40 };
    Budget::new(limits, Arc::new(AtomicBool::new(false))).unwrap()
}

// Each case paired with its expected result, after the header checks every replay shares.
fn load(set: &str, cases: &[u8], expected: &[u8]) -> Vec<(Json, Json)> {
    let digest = Sha256::digest(cases).iter().map(|byte| format!("{byte:02x}")).collect::<String>();
    let expected: Json = serde_json::from_slice(expected).unwrap();
    assert_eq!(expected["fixtureSha256"].as_str(), Some(digest.as_str()), "{set}: the expected file is stale");
    let cases: Json = serde_json::from_slice(cases).unwrap();
    let cases = cases["cases"].as_array().unwrap();
    let results = expected["cases"].as_array().unwrap();
    assert!(!cases.is_empty(), "{set}: no cases");
    assert_eq!(cases.len(), results.len(), "{set}: case count");
    cases.iter().zip(results).map(|(case, result)| {
        assert_eq!(case["id"], result["id"], "{set}: case order");
        (case.clone(), result["result"].clone())
    }).collect()
}

fn check(set: &str, pairs: &[(Json, Json)], mut matches: impl FnMut(&Json, &Json) -> Result<(), String>) {
    let mismatches = pairs.iter().filter_map(|(case, expected)| matches(case, expected).err().map(|reason| format!("{}: {reason}", case["id"])))
        .collect::<Vec<_>>();
    println!("{set}: {} cases, {} mismatches", pairs.len(), mismatches.len());
    assert!(mismatches.is_empty(), "{set}: {} of {} cases differ:\n{}", mismatches.len(), pairs.len(), mismatches.join("\n"));
}

fn units(text: &Json) -> Vec<u16> {
    match text {
        Json::String(value) => value.encode_utf16().collect(),
        _ => text["u"].as_array().unwrap().iter().map(|unit| unit.as_u64().unwrap() as u16).collect(),
    }
}
fn text(value: &Json, budget: &Budget) -> Text { Text::from_units(&units(value), budget).unwrap() }
fn number(repr: &str) -> f64 {
    match repr { "-0" => -0.0, "NaN" => f64::NAN, "Infinity" => f64::INFINITY, "-Infinity" => f64::NEG_INFINITY, _ => repr.parse().unwrap() }
}
fn same_number(expected: f64, actual: f64) -> bool { if expected.is_nan() { actual.is_nan() } else { expected.to_bits() == actual.to_bits() } }

fn decode(value: &Json, budget: &Budget) -> Value {
    match value[0].as_str().unwrap() {
        "undefined" => Value::Undefined,
        "null" => Value::Null,
        "bool" => Value::Bool(value[1].as_bool().unwrap()),
        "number" => Value::Number(number(value[1].as_str().unwrap())),
        "string" => Value::Text(text(&value[1], budget)),
        "array" => {
            let mut items = OwnedVec::new(budget).unwrap();
            for item in value[1].as_array().unwrap() { items.push(decode(item, budget)).unwrap(); }
            Value::Array(items)
        }
        "object" => {
            let mut entries = OwnedVec::new(budget).unwrap();
            for entry in value[1].as_array().unwrap() { entries.push((text(&entry[0], budget), decode(&entry[1], budget))).unwrap(); }
            Value::Object(entries)
        }
        tag => panic!("unknown tag {tag}"),
    }
}

// Structural equality with the tagged value Node produced; numbers compare by bits, strings by UTF-16 units.
fn same(expected: &Json, actual: &Value) -> bool {
    match (expected[0].as_str().unwrap(), actual) {
        ("undefined", Value::Undefined) | ("null", Value::Null) => true,
        ("bool", Value::Bool(value)) => expected[1].as_bool() == Some(*value),
        ("number", Value::Number(value)) => same_number(number(expected[1].as_str().unwrap()), *value),
        ("string", Value::Text(value)) => units(&expected[1]) == value.units().collect::<Vec<_>>(),
        ("array", Value::Array(items)) => {
            let expected = expected[1].as_array().unwrap();
            expected.len() == items.as_slice().len() && expected.iter().zip(items.as_slice()).all(|(expected, item)| same(expected, item))
        }
        ("object", Value::Object(entries)) => {
            let expected = expected[1].as_array().unwrap();
            expected.len() == entries.as_slice().len() && expected.iter().zip(entries.as_slice())
                .all(|(expected, (key, value))| units(&expected[0]) == key.units().collect::<Vec<_>>() && same(&expected[1], value))
        }
        _ => false,
    }
}

fn shown(value: &Text) -> String { String::from_utf16_lossy(&value.units().collect::<Vec<_>>()) }
fn compare_text(expected: &Json, actual: &Text) -> Result<(), String> {
    if units(expected) == actual.units().collect::<Vec<_>>() { Ok(()) } else { Err(format!("expected {expected}, got {:?}", shown(actual))) }
}

// A JSON.parse result: the tagged value and its JSON.stringify text, or a SyntaxError.
fn compare_parse(parsed: Result<Value, Error>, expected: &Json, budget: &Budget) -> Result<(), String> {
    match (parsed, expected.get("error")) {
        (Err(Error::Syntax { .. }), Some(_)) => Ok(()),
        (Ok(value), None) => {
            if !same(&expected["value"], &value) { return Err(format!("value differs: {value:?}")); }
            compare_text(&expected["text"], &json::stringify(&value, budget).unwrap().unwrap())
        }
        (result, _) => Err(format!("expected {expected}, got {result:?}")),
    }
}

#[test]
fn oracle_json_parse() {
    check("json-parse", &oracle_set!("json-parse"), |case, expected| {
        let budget = budget();
        compare_parse(json::parse(case["source"].as_str().unwrap(), &budget), expected, &budget)
    });
}

#[test]
fn oracle_json_parse_units() {
    check("json-parse-units", &oracle_set!("json-parse-units"), |case, expected| {
        let budget = budget();
        compare_parse(json::parse_text(&text(&case["source"], &budget), &budget), expected, &budget)
    });
}

#[test]
fn oracle_json_stringify() {
    check("json-stringify", &oracle_set!("json-stringify"), |case, expected| {
        let budget = budget();
        match (json::stringify(&decode(&case["value"], &budget), &budget).unwrap(), expected.get("text")) {
            (None, None) => Ok(()),
            (Some(actual), Some(text)) => compare_text(text, &actual),
            (actual, _) => Err(format!("expected {expected}, got {:?}", actual.as_ref().map(shown))),
        }
    });
}

#[test]
fn oracle_number_to_string() {
    check("number-to-string", &oracle_set!("number-to-string"), |case, expected| {
        let budget = budget();
        let value = f64::from_bits(u64::from_str_radix(case["bits"].as_str().unwrap(), 16).unwrap());
        compare_text(&expected["text"], &num::number_to_text(value, &budget).unwrap())
    });
}

#[test]
fn oracle_number_from_text() {
    check("number-from-text", &oracle_set!("number-from-text"), |case, expected| {
        let budget = budget();
        let actual = num::to_number(&text(&case["text"], &budget), &budget).unwrap();
        let expected = number(expected["number"].as_str().unwrap());
        if same_number(expected, actual) { Ok(()) } else { Err(format!("expected {expected:?}, got {actual:?}")) }
    });
}

#[test]
fn oracle_trim() {
    check("trim", &oracle_set!("trim"), |case, expected| {
        let budget = budget();
        let value = text(&case["text"], &budget);
        compare_text(&expected["trim"], &value.trim(&budget).unwrap()).map_err(|reason| format!("trim: {reason}"))?;
        compare_text(&expected["trimStart"], &value.trim_start(&budget).unwrap()).map_err(|reason| format!("trimStart: {reason}"))?;
        compare_text(&expected["trimEnd"], &value.trim_end(&budget).unwrap()).map_err(|reason| format!("trimEnd: {reason}"))
    });
}

// A contract set: the generator restates the TS construction order instead of running the TS builders.
#[test]
fn oracle_prompt_message() {
    check("prompt-message", &oracle_set!("prompt-message"), |case, expected| {
        let budget = budget();
        let value = decode(&case["value"], &budget);
        let round_trip = match case["kind"].as_str().unwrap() {
            "message" => PromptMessage::from_value(value, &budget).and_then(|message| message.to_value(&budget)),
            _ => Multimodal::from_value(value, &budget).and_then(|multimodal| multimodal.to_value(&budget)),
        }.map_err(|error| format!("conversion failed: {error:?}"))?;
        compare_text(&expected["text"], &json::stringify(&round_trip, &budget).unwrap().unwrap())
    });
}
